import re, heapq

# Parse gates exactly like the C code does
gates = {}
num_signals = 0
with open('gates.txt') as f:
    for line in f:
        line = line.strip()
        if not line: continue
        m = re.match(r'out(\d+) = (.+)', line)
        if not m: continue
        out_idx = int(m.group(1))
        op = m.group(2)
        if out_idx >= num_signals:
            num_signals = out_idx + 1
        gates[out_idx] = op

print('num_signals:', num_signals)

# Build dependents
dependents = [[] for _ in range(num_signals)]
for sig, op in gates.items():
    srcs = set()
    if op == '0' or op == '1':
        pass
    elif op.startswith('~out'):
        srcs.add(int(op[4:]))
    elif re.match(r'out\d+$', op):
        srcs.add(int(op[3:]))
    else:
        for s in re.findall(r'out(\d+)', op):
            srcs.add(int(s))
    srcs.discard(sig)
    for s in srcs:
        if s < num_signals:
            dependents[s].append(sig)

def eval_gate(sig, values):
    op = gates[sig]
    if op == '0': return 0
    if op == '1': return 1
    if op.startswith('~out'):
        return 1 - values[int(op[4:])]
    if re.match(r'out\d+$', op):
        return values[int(op[3:])]
    m = re.match(r'out(\d+) (\^|&|\|) out(\d+)', op)
    if m:
        a, b = values[int(m.group(1))], values[int(m.group(3))]
        if m.group(2) == '^': return a ^ b
        if m.group(2) == '&': return a & b
        if m.group(2) == '|': return a | b
    return 0

